        ppsScenarioAddBUS_LOAD_W(builder, self.BUS_LOAD_W)
        ppsScenarioAddSENSOR_NOISE_ARCSEC(builder, self.SENSOR_NOISE_ARCSEC)
        if self.RELATIVE_TARGET_ID is not None:
            ppsScenarioAddRELATIVE_TARGET_ID(builder, RELATIVE_TARGET_ID)
        ppsScenario = ppsScenarioEnd(builder)
        return ppsScenario
